import sys
import json
import os
import hashlib
import subprocess
from typing import Optional

def read_token() -> Optional[str]:
    token_path = '/etc/auditrun/token'
    if not os.path.exists(token_path):
        return None
    with open(token_path, 'r') as f:
        content = f.read().rstrip('\n')
        return content if content else None

def validate_token(token: str) -> bool:
    return token.startswith('audit_')

def compute_signature(command: str, stdout: str, stderr: str, exit_code: int) -> str:
    data = f"{command}\n{stdout}\n{stderr}\n{exit_code}".encode('utf-8')
    return hashlib.sha256(data).hexdigest()

def run_command(command: str) -> tuple[str, str, int]:
    try:
        result = subprocess.run(
            command,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            check=False
        )
        return result.stdout, result.stderr, result.returncode
    except Exception:
        return '', '', 1

def main():
    if len(sys.argv) != 2:
        sys.stderr.write('not authorized\n')
        sys.exit(1)

    command = sys.argv[1]
    token = read_token()
    if not token or not validate_token(token):
        sys.stderr.write('not authorized\n')
        sys.exit(1)

    stdout, stderr, exit_code = run_command(command)

    signature = compute_signature(command, stdout, stderr, exit_code)

    output = {
        'command': command,
        'exit_code': exit_code,
        'signature': signature,
        'stderr': stderr,
        'stdout': stdout
    }

    sorted_output = dict(sorted(output.items()))
    print(json.dumps(sorted_output))

if __name__ == '__main__':
    main()

import sys
import json
import hashlib
import os

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("not authorized\n")
        sys.exit(1)

    command = sys.argv[1]

    try:
        with open('/etc/auditrun/token', 'r') as token_file:
            token = token_file.read().rstrip('\n')
    except (IOError, OSError):
        sys.stderr.write("not authorized\n")
        sys.exit(1)

    if not token.startswith('audit_'):
        sys.stderr.write("not authorized\n")
        sys.exit(1)

    try:
        result = os.popen(command).read()
        exit_code = os.waitpid(-1, os.WNOHANG)[0] >> 8
    except Exception:
        sys.stderr.write("not authorized\n")
        sys.exit(1)

    data = {
        'command': command,
        'exit_code': exit_code,
        'stdout': result,
        'signature': hashlib.sha256(
            (command + '\n' + result + '\n' + str(exit_code)).encode('utf-8')
        ).hexdigest()
    }

    sys.stdout.write(json.dumps(data) + '\n')
    sys.exit(0)

if __name__ == '__main__':
    main()
